const data={bug:['奇特昆虫','一只不太像昆虫的昆虫','你好，我的六条腿有点特别。','你可以问我：我为什么长成这样？我和树叶为什么会互相模仿？','bug'],painting:['现代主义画','一幅不急着解释的画','你看到的是形状，还是一种感觉？','为什么现代主义画家把世界拆成颜色、线条和几何形状？','painting'],fridge:['冰箱','一台把冬天留在家里的机器','我每天都在制造一点凉快。','冷气去了哪里？冰箱为什么会发出嗡嗡声？','fridge'],tower:['伪装信号塔','一棵站得很高的伪装树','我长得像树，也在和远方说话。','信号是怎么穿过城市的？为什么有人要把我藏进树里？','tower'],shop:['便利店','一盏晚一点才会熄灭的灯','欢迎光临，今晚想带走什么？','便利店为什么总在附近？一件商品是怎样来到货架上的？','shop']};
function go(name){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));const target=document.querySelector('.screen-'+name);if(target)target.classList.add('active');document.querySelectorAll('.watch-tabs button').forEach(x=>x.classList.remove('selected'));const tab=document.querySelector('.watch-tabs button[data-go="'+name+'"]')||document.querySelector('.watch-tabs button[data-go="home"]');if(tab)tab.classList.add('selected')}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.go)));
document.querySelectorAll('.object-list button').forEach(b=>b.addEventListener('click',()=>{const d=data[b.dataset.object];document.querySelector('[data-title]').textContent=d[0];document.querySelector('[data-kicker]').textContent=d[1];document.querySelector('[data-line]').textContent=d[2];document.querySelector('[data-description]').textContent=d[3];document.querySelector('[data-hero]').className='object-hero '+d[4];go('object')}));
document.querySelectorAll('[data-platform]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-platform]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('.watch-view').classList.toggle('hidden',b.dataset.platform!=='watch');document.querySelector('.parent-view').classList.toggle('hidden',b.dataset.platform!=='parent')}));
